const DICTS = { uk, en, ru };
let cur = ['uk', 'en', 'ru'].includes(langCode()) ? langCode() : 'uk';

export function setLang(l) { if (DICTS[l]) cur = l; }
export const lang = () => cur;
export function t(key, params) {
  let s = (DICTS[cur] && DICTS[cur][key]) || uk[key];
  if (s === undefined) return key;
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] !== undefined && params[k] !== null ? String(params[k]) : m));
  return s;
}
